#'
#' @export
FrequencyDistribution <- function(
    data,
    x,
    groups = 10,
    sgd = FALSE,
    i = 0) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("FrequencyDistribution requires jmvcore to be installed (restart may be required)")

    if ( ! missing(x)) x <- jmvcore::resolveQuo(jmvcore::enquo(x))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(x), x, NULL))


    options <- FrequencyDistributionOptions$new(
        x = x,
        groups = groups,
        sgd = sgd,
        i = i)

    analysis <- FrequencyDistributionClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

